        if …3497 tokens truncated…rgba(16,22,38,0.8)',
        borderRadius: '3px',
        padding: '1px 2px',
        pointerEvents: 'none',
      });
      btn.appendChild(countBadge);

      // Content-DSL charge badge: show first numeric status line as a
      // compact overlay on the quick slot (e.g. "3/8" for charges)
